const DETAILS={"Adrahil": {"s": "Adrahil I was a Prince of Gondor who lived around TA 1944 in the land of Belfalas.", "f": [["Title", "Prince of Belfalas"], ["Also known as", "Adrahil of Dol Amroth"], ["Culture", "Men of Gondor"], ["Born", "Before TA 1944"]], "u": "https://lotr.fandom.com/wiki/Adrahil_I"}, "Aegnor": {"s": "Aegnor was a Ñoldorin Elf, the third son of Finarfin, elder brother of Galadriel, younger brother of Finrod Felagund and Angrod and lord of the Ñoldor of Dorthonion in the First Age.", "f": [["Title", "Lord of Dorthonion with Angrod"], ["Also known as", "Egnor, Aikanár, Aikanáro"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finarfin), Falmari (House of Olwë)"], ["Born", "YT ? during the Noontide of Valinor"], ["Died", "FA 455"], ["Hair", "Golden"]], "u": "https://lotr.fandom.com/wiki/Aegnor"}, "Amandil": {"s": "Amandil was the leader of the Faithful in Númenor and became the eighteenth and last Lord of Andúnië. His role as Lord of Andúnië and his dedication as one of the Faithful paved the way for the High Kings of Gondor and Arnor, ensuring their traditions were upheld by the Dúnedain of Middle-earth, culminating in Aragorn II Elessar. Elendil the Tall was his son, and Isildur his grandson.", "f": [["Title", "Lord of Andúnië"], ["Race", "Men"], ["Culture", "Númenóreans, (House of Elros), Faithful}}"], ["Born", "Late Second Age ?"], ["Died", "Sailed west either SA 3310 or SA 3316; fate untold"]], "u": "https://lotr.fandom.com/wiki/Amandil"}, "Amras": {"s": "Amras and his younger twin brother, Amrod, were Ñoldorin princes, the youngest of the seven Sons of Fëanor. Through their mother Nerdanel's line, they inherited red hair, instead of Fëanor's dark hair.", "f": [["Title", "Lord of Estolad"], ["Also known as", "Pityafinwë, Nityafinwë, Minyarussa, Umbarto/Ambarto and Ambarussa (Q, mn), Minyarussa and Atyarussa (Q, epessë), Ambarussa"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "After YT 1190"], ["Died", "FA 538"], ["Hair", "Red"], ["Weapon", "Sword ?, Bow"]], "u": "https://lotr.fandom.com/wiki/Amras"}, "Amrod": {"s": "Amrod was the second-youngest of the seven sons of Fëanor, son of Finwë.", "f": [["Also known as", "Ambarussa, Ambarto, Umbarto, Telufinwë"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "Years of the Trees"], ["Died", "FA 538"], ["Hair", "Dark red"], ["Weapon", "Sword, bow"]], "u": "https://lotr.fandom.com/wiki/Amrod"}, "Amrothos": {"s": "Amrothos was the third son and child of Imrahil, the twenty-second Prince of Dol Amroth.", "f": [["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Dol Amroth)"], ["Born", "TA 2994"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Amrothos"}, "Angrod": {"s": "Angrod was a Ñoldorin Elf, the second son of Finarfin and lord of the Ñoldor of Dorthonion. He was the father of Orodreth and subsequently grandfather of the famed Gil-galad.", "f": [["Title", "Lord of Dorthonion with Aegnor"], ["Also known as", "Angaráto"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finarfin), Falmari (House of Olwë)"], ["Born", "YT ?"], ["Died", "FA 455"], ["Hair", "Golden"]], "u": "https://lotr.fandom.com/wiki/Angrod"}, "Anárion": {"s": "Anárion was the youngest son of Elendil, the High King of Arnor and Gondor. He and his brother Isildur jointly ruled Gondor, while their father dwelt in the North. Following his father's death during the Siege of Barad-dûr, and Isildur's death at the Disaster of the Gladden Fields, the kingship of Gondor was committed to the line of Anárion beginning with his son, Meneldil.", "f": [["Title", "King of Gondor"], ["Race", "Men"], ["Born", "SA 3219"], ["Died", "SA 3440"], ["Played by", "Andrew Richardson"]], "u": "https://lotr.fandom.com/wiki/An%C3%A1rion"}, "Ar-Pharazôn": {"s": "Ar-Pharazôn, or Tar-Calion, later titled \"the Golden\", was the twenty-fifth and last King of Númenor. Of all the rulers of Númenor, he wielded the most power, but used it most unwisely; his desire for eternal life which Sauron intentionally and deceptively exploited, caused the Downfall of Númenor and the Change of the World.", "f": [["Title", "King of Númenor, \"King of Men\", \"King of the Sea\""], ["Also known as", "Tar-Calion (Q), \"The Golden\""], ["Race", "Men"], ["Culture", "Númenóreans (King's Men), House of Elros"], ["Born", "SA 3118"], ["Died", "Imprisoned in the Caves of the Forgotten in SA 3319"], ["Weapon", "Aranrúth"]], "u": "https://lotr.fandom.com/wiki/Ar-Pharaz%C3%B4n"}, "Arador": {"s": "Arador was the fourteenth Chieftain of the Dúnedain and the father of Arathorn II and grandfather of Aragorn II.", "f": [["Title", "Chieftain of the Dúnedain"], ["Race", "Men"], ["Culture", "Dúnedain of the North, (House of Isildur), Rangers of the North"], ["Born", "TA 2820"], ["Died", "TA 2930"], ["Weapon", "Chieftain's sword, shards of Narsil"], ["Played by", "Iain Marshall"]], "u": "https://lotr.fandom.com/wiki/Arador"}, "Aragorn II Elessar": {"s": "Aragorn II, son of Arathorn II and Gilraen, also known as Strider and Elessar, was the 16th and last Chieftain of the Dúnedain of the North; later crowned King Elessar Telcontar (March 1, 2931 - FO 120), the 26th King of Arnor, 35th King of Gondor and first High King of Gondor and Arnor since the short reign of Isildur. He was a great ranger and warrior. As Isildur's heir, he bore the shards of Narsil, reforged and renamed Andúril (\"Flame of the West\") in the War of the Ring.", "f": [["Title", "Chieftain of the Dúnedain, Isildurioni, High King of the Dúnedain, King of Arnor, King of Gondor"], ["Also known as", "Estel, Thorongil, Elessar / Edhelharn, Telcontar, Envinyatar, Strider, The Dúnadan, Wingfoot"], ["Race", "Men"], ["Culture", "Dúnedain of the North (House of Isildur, founded the House of Telcontar)"], ["Born", "March 1, TA 2931"], ["Died", "March 1, FO 120"], ["Height", "6'6\""], ["Hair", "Dark, flecked with grey"], ["Eyes", "Grey"], ["Weapon", "Andúril (sword), bow, spear"], ["Played by", "Viggo Mortensen (live-action films), Andrey Tenetko (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Aragorn_II"}, "Arathorn II": {"s": "Arathorn II was the fifteenth Chieftain of the Dúnedain and father of the future Aragorn II, who reunited the lost kingdom of Arnor with Gondor.", "f": [["Title", "Chieftain of the Dúnedain, Isildurioni"], ["Race", "Men"], ["Culture", "Dúnedain of the North (Rangers of the North)"], ["Born", "TA 2873"], ["Died", "TA 2933"], ["Weapon", "Shards of Narsil, Chieftain's sword"]], "u": "https://lotr.fandom.com/wiki/Arathorn_II"}, "Aredhel": {"s": "Aredhel, also known as Aredhel Ar-Feiniel, the \"White Lady of the Ñoldor\", was the only daughter and third child of Ñoldorin High-prince Fingolfin and his wife, Anairë. Aredhel was the sister of Fingon, Turgon, and Argon, and the mother of Maeglin.", "f": [["Title", "Princess of Gondolin"], ["Also known as", "Aredhel Ar-Feiniel, Irissë, Isfin"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fingolfin), Gondolindrim"], ["Born", "YT 1362"], ["Died", "FA 400"], ["Height", "Tall"], ["Hair", "Dark"]], "u": "https://lotr.fandom.com/wiki/Aredhel"}, "Argon": {"s": "Argon was the fourth child and the youngest son of Fingolfin, the High King of the Ñoldor in Beleriand. He was one of the mighty Prince of the Ñoldor in Tirion, Valinor. Furthermore, Argon grew up in Valinor, until later, the Ñoldor went into exile for Middle-earth where he journeyed with his father Fingolfin and his siblings.", "f": [["Title", "Prince of the Ñoldor"], ["Also known as", "Arakáno"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fingolfin)"], ["Born", "After YT 1362"], ["Died", "YT 1500, Battle of the Lammoth"], ["Height", "Tallest of his siblings"], ["Hair", "Possibly dark"], ["Weapon", "Sword"]], "u": "https://lotr.fandom.com/wiki/Argon"}, "Arwen": {"s": "Arwen was the Half-elven daughter of Elrond and Celebrían. She was often called Arwen Undómiel or \"Evenstar\".", "f": [["Title", "Lady of Rivendell, Queen of the Reunited Kingdom"], ["Also known as", "Undómiel (Quenya for \"Evenstar\")"], ["Race", "Half-elf (chose to be mortal)"], ["Culture", "Elves of Lindon, Elves of Rivendell"], ["Born", "TA 241"], ["Died", "FO 121 (aged 2901), Cerin Amroth"], ["Hair", "Black"], ["Eyes", "Grey"], ["Played by", "Liv Tyler"]], "u": "https://lotr.fandom.com/wiki/Arwen"}, "Balbo Baggins": {"s": "Balbo Baggins was a hobbit of the Shire and the first recorded member of the Baggins family. He was the great-grandfather of Bilbo, great-great-grandfather of Frodo and great-great-great grandfather of Merry and Pippin.", "f": [["Race", "Hobbits"], ["Culture", "Shire-hobbits (Baggins family)"], ["Born", "TA 2767 (SR 1167)"], ["Died", "TA 2858 (SR 1258)"]], "u": "https://lotr.fandom.com/wiki/Balbo_Baggins"}, "Balin": {"s": "Balin was a Dwarf leader, the son of Fundin, and elder brother of Dwalin. He was one of the thirteen Dwarves who accompanied Thorin II Oakenshield on the quest to regain the Lonely Mountain.", "f": [["Title", "Lord of Moria"], ["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2763, Erebor"], ["Died", "November 10, TA 2994, Kheled-zâram"], ["Height", "About 4'0\" at least"], ["Hair", "White"], ["Weapon", "Sword"], ["Played by", "Ken Stott"]], "u": "https://lotr.fandom.com/wiki/Balin"}, "Barahir": {"s": "Barahir was an Edain man of Dorthonion during the First Age, heir to the House of Bëor and youngest child of Bregor, fifth chieftain of the People of Bëor. He was also the fourth Lord of Ladros and the seventh and probably last Chieftain of the Bëorians after his deceased elder brother Bregolas. Besides his elder brother, Barahir had three elder sisters: Bregil, Hirwen, and Gilwen.", "f": [["Title", "Chieftain of the House of Bëor, Lord of Ladros, Captain of the Outlaws of Dorthonion"], ["Race", "Men"], ["Culture", "Edain (House of Bëor)"], ["Born", "FA 400"], ["Died", "FA 460"], ["Hair", "Possibly dark"], ["Weapon", "Sword, bow"]], "u": "https://lotr.fandom.com/wiki/Barahir"}, "Beren": {"s": "Beren, also called Beren Erchamion, was a man of the First House of the Edain, and one time Lord of Dorthonion. He was a hero whose romance with the Elf-maiden Lúthien was one of the great stories of the Elder Days told for many ages after.", "f": [["Title", "Chieftain of the House of Bëor, Lord of Tol Galen"], ["Also known as", "Erchamion, Camlost"], ["Race", "Men"], ["Culture", "Edain (House of Bëor, XII Bëorings)"], ["Born", "FA 432"], ["Died", "FA 466 (subsequently resurrected), FA 503 (aged 71)"], ["Height", "Tall"], ["Hair", "Golden-brown"], ["Eyes", "Grey"], ["Weapon", "Dagmor (sword), Angrist (knife), bow"]], "u": "https://lotr.fandom.com/wiki/Beren"}, "Bifur": {"s": "Bifur was a Dwarf of the late Third Age. He is best known for being a companion to Bilbo Baggins and Thorin II on the quest to regain the Lonely Mountain, along with his cousins Bofur and Bombur.", "f": [["Race", "Dwarves"], ["Culture", "Dwarves of Khazad-dûm"], ["Born", "Late Third Age"], ["Died", "Before FO 91"], ["Height", "About 4'0\" at least"], ["Hair", "Black and white"], ["Weapon", "Boar spear"], ["Played by", "William Kircher"]], "u": "https://lotr.fandom.com/wiki/Bifur"}, "Bilbo Baggins": {"s": "Bilbo Baggins was a hobbit of the Shire in the Third Age. He was hired by Gandalf to aid Thorin and Company in the Quest of Erebor, over the course of which he became a bearer of the One Ring and fought in the Battle of Five Armies. Upon his return home, he wrote of most of his adventures in a book he called There and Back Again, and garnered great fame among hobbits and across Middle-earth.", "f": [["Title", "Elf-friend, Ring-bearer, Burglar, Barrel-rider, et al."], ["Also known as", "Mr. Invisible Baggins, Bilbo Took (see more)"], ["Race", "Hobbits"], ["Culture", "Shire-folk (Baggins)"], ["Born", "September 22, TA 2890 (SR 1290)"], ["Died", "Sometime after September 29, TA 3021 (aged at least 131), Undying Lands"], ["Height", "3'0\" or 3'6\""], ["Hair", "Brown, later white"], ["Eyes", "Blue"], ["Weapon", "Sting"]], "u": "https://lotr.fandom.com/wiki/Bilbo_Baggins"}, "Bofur": {"s": "Bofur was a Dwarf who lived in the late Third Age. He is best known as a companion of Bilbo Baggins, Thorin Oakenshield, and Gandalf on the quest to reclaim the Lonely Mountain from the dragon Smaug, along with his brother Bombur and cousin Bifur.", "f": [["Race", "Dwarves"], ["Culture", "Unknown; possibly Firebeards or Broadbeams"], ["Born", "Late Third Age"], ["Died", "Before FO 91"], ["Hair", "Brown"], ["Eyes", "Hazelnut"], ["Played by", "James Nesbitt (in the Peter Jackson trilogy)"]], "u": "https://lotr.fandom.com/wiki/Bofur"}, "Bombur": {"s": "Bombur was a Dwarf who accompanied Thorin Oakenshield and Bilbo Baggins on their quest to the Lonely Mountain as part of the company, alongside his brother Bofur and cousin Bifur. Bombur was noted as the fattest Dwarf in the company.", "f": [["Race", "Dwarves"], ["Culture", "Unknown; possibly Firebeards or Broadbeams"], ["Born", "Late Third Age"], ["Died", "Before FO 91|siblings = Bofur|height=About 4'0\" at least|realms=Erebor}}"], ["Hair", "Red"], ["Weapon", "Iron Ladle"], ["Played by", "Stephen Hunter"]], "u": "https://lotr.fandom.com/wiki/Bombur"}, "Borin": {"s": "Borin was a Dwarf of Durin's Folk, the second son of King Náin II and brother of Dáin I.", "f": [["Race", "Dwarven"], ["Culture", "Durin's Folk"], ["Born", "TA 2450"], ["Died", "TA 2711"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/Borin"}, "Boromir": {"s": "Boromir was a valiant warrior of Gondor, renowned for his prowess in combat and skill on the battlefield. He was the eldest son of Denethor II, who was Steward of Gondor during the War of the Ring, and his wife Finduilas. Even the people of Rohan admired him, particularly Éomer.", "f": [["Title", "Captain of the White Tower, Captain-General, High Warden of the White Tower"], ["Race", "Dunedain"], ["Culture", "Men of Gondor (House of Húrin)"], ["Born", "TA 2978"], ["Died", "February 26, TA 3019 (aged 41), Amon Hen"], ["Height", "6'4\""], ["Hair", "Dark"], ["Eyes", "Grey"], ["Weapon", "Sword, shield"], ["Played by", "Sean Bean (LOTR films); Evgeny Solyakov (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Boromir"}, "Caranthir": {"s": "Caranthir, also known as Caranthir the Dark, was an Elf, the fourth son of Fëanor and the harshest and the quickest to anger of his seven brothers.", "f": [["Title", "Lord of Thargelion, Prince of the Ñoldor"], ["Also known as", "Cranthir, Caranthir the Dark, Carnistir, Morifinwë"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "During the Noontide of Valinor"], ["Died", "FA 506"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Weapon", "Sword, crossbow"]], "u": "https://lotr.fandom.com/wiki/Caranthir"}, "Celeborn": {"s": "Celeborn was the Lord of Lothlórien and husband of Galadriel, Lady of the Golden Wood. He was said to be one of the wisest Elves in Middle-earth at the end of the Third Age.", "f": [["Title", "Lord of Lothlórien, Lord of the Galadhrim, Lord of the Golden Wood, Lord of East Lórien, Prince of Doriath"], ["Also known as", "Teleporno (Quenya)"], ["Race", "Elves"], ["Culture", "Sindar (Elves of Doriath)"], ["Born", "Uncertain; possibly Years of the Trees"], ["Died", "Sailed to Valinor in the early Fourth Age"], ["Height", "6 feet 4 inches (193cm)"], ["Hair", "Silver, long"], ["Played by", "Marton Csokas, Jamie Campbell Bower"]], "u": "https://lotr.fandom.com/wiki/Celeborn"}, "Celebrimbor": {"s": "Celebrimbor was a Ñoldorin prince and the last in the line of the House of Fëanor, who lived in Middle-earth. He was a ruler of Eregion in the Second Age, and a master smith. He is remembered primarily for his creation of the Three Rings of Power: Nenya, Vilya, and Narya, but also he made the second Elfstone (in one version of history) for Galadriel, who would later give it to Aragorn.", "f": [["Title", "Prince of the Ñoldor, Lord of Eregion, Lord of the Gwaith-i-Mírdain"], ["Also known as", "Telperinquar (Quenya)"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor), Elves of Eregion (Gwaith-i-Mírdain)"], ["Born", "During the Years of the Trees in Aman"], ["Died", "SA 1697, Ost-in-Edhil (killed by Sauron)"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Played by", "Charles Edwards"]], "u": "https://lotr.fandom.com/wiki/Celebrimbor"}, "Celebrían": {"s": "Celebrían (IPA:) was an Elven noblewoman, the daughter of Celeborn and Galadriel, the wife of Elrond, and the mother of Elladan, Elrohir, and Arwen.", "f": [["Title", "Lady of Lothlórien, Lady of Rivendell"], ["Race", "Elves"], ["Culture", "Falmari (House of Olwë), Sindar (House of Celeborn), Ñoldor (House of Finarfin), Elves of Rivendell, Galadhrim, Elves of Eregion"], ["Born", "SA 300"], ["Died", "Departed to Aman in TA 2510"], ["Hair", "Possibly silver"]], "u": "https://lotr.fandom.com/wiki/Celebr%C3%ADan"}, "Celegorm": {"s": "Celegorm, called Celegorm the Fair, was the third son of Fëanor and Nerdanel, most closely associated with another brother, Curufin. He is somewhat anomalously described as having fair hair, rather than the black or red hair of his parents and his six siblings.", "f": [["Title", "Lord of Himlad"], ["Also known as", "Celegorm the Fair, Turcafinwë, Tyelkormo"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "During in the Noontide of Valinor"], ["Died", "FA 506, Menelrond"], ["Weapon", "Sword and bow"]], "u": "https://lotr.fandom.com/wiki/Celegorm"}, "Curufin": {"s": "Curufin, also called Curufin the Crafty, was a Ñoldorin prince and the fifth of the seven Sons of Fëanor and Nerdanel. Curufin was the father of Celebrimbor, master Jewel-smith of Eregion who would later forge the three Elvish Rings of Power.", "f": [["Title", "Prince of the Ñoldor, Lord of Himlad (with his brother Celegorm)"], ["Also known as", "Curufin the Crafty, Curufinwë, Atarinkë"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "During the Noontide of Valinor"], ["Died", "FA 506"], ["Hair", "Dark"], ["Weapon", "Sword, bow, Angrist"]], "u": "https://lotr.fandom.com/wiki/Curufin"}, "Círdan": {"s": "Círdan, also known as Nowë and Círdan the Shipwright, was one of the highest and noblest of the Sindar, Lord of the Falathrim during the First Age, and Master of the Grey Havens through the Second, Third, and Fourth Age. He was one of the wisest and most clairvoyant of the Elves, and by the Second Age the oldest known elf in Middle-earth, to remain so throughout that age and into the Fourth Age as well. He was also gifted Narya, one of the Three Rings, by Celebrimbor until he surrendered it to Gandalf.", "f": [["Title", "Lord of the Havens, Master of the Grey Havens, The Shipwright"], ["Also known as", "Nowë, Ciryatan"], ["Race", "Elves"], ["Culture", "Sindar"], ["Born", "Between YT 1050 and YT 1105"], ["Died", "Eventually sailed to Valinor after FO 120"], ["Height", "Very tall"], ["Hair", "Silver, bearded in old age"], ["Played by", "Ben Daniels, Michael Elsworth (Peter Jackson's)"]], "u": "https://lotr.fandom.com/wiki/C%C3%ADrdan"}, "Denethor II": {"s": "Denethor II was the twenty-sixth and last Ruling Steward, also last overall Steward, of Gondor. He was father to War of the Ring heroes Boromir, a member of the Fellowship of the Ring, and Faramir, Captain of the Rangers of Ithilien.", "f": [["Title", "Ruling Steward of Gondor, Lord of Gondor, Lord of Minas Tirith"], ["Race", "Men"], ["Culture", "Men of Gondor (House of Húrin)"], ["Born", "TA 2930"], ["Died", "March 15, 3019 (aged 89) Hallows of Minas Tirith"], ["Hair", "Dark, grey (in old age)"], ["Weapon", "Sword and knife"], ["Played by", "John Noble"]], "u": "https://lotr.fandom.com/wiki/Denethor_II"}, "Dior": {"s": "Dior, also known as Dior Eluchîl, was the son of Beren Erchamion of the House of Bëor and the princess Lúthien Tinúviel, daughter of King Thingol and Melian. He later became the second (and last) King of Doriath as the only heir of Thingol, and thereby the High King of the Sindar also. Dior was called the Fair and was the first Half-elf in Middle-earth's history, for his father was of the race of Men, and his mother inherited Elven blood.", "f": [["Title", "King of Doriath, High King of the Sindar"], ["Also known as", "The Fair, Aranel, Ausir, Eluchîl"], ["Race", "Half-elves (¼ Elf, ½ Man, ¼ Maia)"], ["Culture", "Edain (House of Bëor), Sindar (House of Thingol)"], ["Born", "FA 470, Tol Galen"], ["Died", "FA 506, Second Kinslaying (aged 36)"], ["Height", "Tall"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Weapon", "Aranrúth (sword)"]], "u": "https://lotr.fandom.com/wiki/Dior"}, "Dori": {"s": "Dori was a Dwarf of Durin's Folk, who, along with his brother Nori and cousin Ori, travelled with Bilbo Baggins and Thorin II as a member of Thorin's Company on the Quest for Erebor, to reclaim the Lonely Mountain from the dragon Smaug.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Played by", "Mark Hadlow (The Hobbit trilogy)"]], "u": "https://lotr.fandom.com/wiki/Dori"}, "Durin the Deathless": {"s": "Durin I of Khazad-dûm, known also as Durin the Deathless, was the oldest of the Seven Fathers of the Dwarves, first created by Aulë the Vala; and as such, the first living being that was not of the Ainur.", "f": [["Title", "King of Durin's Folk, King of Khazad-dûm"], ["Also known as", "Durin the Deathless"], ["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "Between Years of the Trees, 1132 & 1150"], ["Died", "Late First Age"], ["Height", "About 4'0\" at least"], ["Weapon", "Durin's Axe"]], "u": "https://lotr.fandom.com/wiki/Durin_I"}, "Dwalin": {"s": "Dwalin was one of the Dwarves who traveled with Bilbo and Gandalf as a member of Thorin and Company on the quest to regain the Lonely Mountain from the Dragon Smaug. He was the brother of Balin and the youngest son of Fundin.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2772, Dunland"], ["Died", "FO 91, Erebor"], ["Hair", "Blue beard"], ["Eyes", "Bright eyes|height=About 4'0\" at least}}"], ["Weapon", "Axe(s)"], ["Played by", "Graham McTavish"]], "u": "https://lotr.fandom.com/wiki/Dwalin"}, "Dáin I": {"s": "Dáin I was a Dwarf and a King of Durin's Folk in the Third Age. He was the son of Náin II and had a younger brother, Borin. He had three sons: Thrór, Frór, and Grór.", "f": [["Title", "King of Durin's Folk"], ["Race", "Dwarves"], ["Born", "TA 2440"], ["Died", "TA 2589"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/D%C3%A1in_I"}, "Dáin II Ironfoot": {"s": "Dáin II Ironfoot (or King Dáin), the son of Náin and great-grandson of Dáin I of Durin's Folk. He was a Dwarf King of Durin's Folk, the Lord of the Iron Hills, and the fifth King under the Mountain during the War of the Ring in Middle-earth.", "f": [["Title", "Lord of the Iron Hills, King of Durin's Folk, King under the Mountain"], ["Also known as", "Ironfoot"], ["Race", "Dwarves"], ["Culture", "Durin's Folk (Dwarves of the Iron Hills)"], ["Born", "TA 2767"], ["Died", "March 17, 3019 (aged 252), Battle of Dale"], ["Height", "About 4'0\" at least"], ["Weapon", "Red Axe"], ["Played by", "Billy Connolly"]], "u": "https://lotr.fandom.com/wiki/D%C3%A1in_II"}, "Dís": {"s": "Dís was a Dwarf woman of Durin's Folk.", "f": [["Title", "Princess of Durin’s Folk"], ["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Lonely Mountain"], ["Born", "TA 2760"], ["Died", "TA 2942"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/D%C3%ADs"}, "Ecthelion II": {"s": "Ecthelion II was the twenty-fifth Ruling Steward of Gondor.", "f": [["Title", "Ruling Steward of Gondor, Lord of Gondor"], ["Race", "Men"], ["Culture", "Men of Gondor (House of Húrin)"], ["Born", "TA 2886"], ["Died", "TA 2984 (aged 98)"]], "u": "https://lotr.fandom.com/wiki/Ecthelion_II"}, "Elanor the Fair": {"s": "Elanor Fairbairn (née Gamgee/Gardner) or Elanor the Fair was the first daughter of Samwise Gamgee and Rosie Cotton.", "f": [["Title", "Keeper of the Red Book of Westmarch"], ["Race", "Hobbits"], ["Culture", "Shire-folk (Gamgee family, Gardner family, & Fairbairn family)"], ["Born", "March 25, 3021 (SR 1421)"], ["Hair", "Golden"], ["Played by", "Alexandra Astin"]], "u": "https://lotr.fandom.com/wiki/Elanor_%28Gardner%29_Fairbairn"}, "Elboron": {"s": "Elboron was the son of Faramir and Éowyn.", "f": [["Title", "Prince of Ithilien, Lord of Emyn Arnen, Steward of Gondor"], ["Race", "Men"], ["Culture", "Gondorians (House of Húrin)"]], "u": "https://lotr.fandom.com/wiki/Elboron"}, "Eldarion": {"s": "Eldarion (Quenya: \"Scion of the Eldar\") was the only son and heir of Aragorn II, King of the Reunited Kingdom, and his wife, Queen Arwen Undómiel.", "f": [["Title", "High King of the Reunited Kingdom"], ["Race", "Half-elves (mortal fate)"], ["Culture", "Dúnedain of Gondor (House of Telcontar)"], ["Born", "FO 1"], ["Died", "Possibly FO 220"], ["Height", "Tall"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Played by", "Sadwyn Brophy (film)"]], "u": "https://lotr.fandom.com/wiki/Eldarion"}, "Elendil": {"s": "Elendil (Quenya: \"Elf-friend\" or \"Star-lover\"), also known as Elendil the Tall/the Fair or Voronda (\"The Faithful\"), was a man of Númenor and the father of Isildur and Anárion who led the survivors of its Downfall to the shores of Middle-earth where they founded two Realms in Exile: Arnor and Gondor. Thus, Elendil became the first King of both realms and held the title of first High King of the Dúnedain, making him supreme overlord of all exiled Númenóreans in the lands east of the Great Sea.", "f": [["Title", "High King of the Dúnedain, King of Arnor, King of Gondor"], ["Also known as", "The Tall, the Fair, Voronda (Q.), Nimruzîr (Adûnaic)"], ["Race", "Men"], ["Culture", "Faithful Númenóreans (Lords of Andúnië)"], ["Born", "SA 3119, Númenor"], ["Died", "SA 3441 Siege of Barad-dûr"], ["Height", "7'11\" or 7'0\""], ["Hair", "Dark"], ["Eyes", "Grey"], ["Played by", "Peter McKenzie (film), Lloyd Owen"]], "u": "https://lotr.fandom.com/wiki/Elendil"}, "Elfwine": {"s": "Elfwine was the son of Éomer and the nineteenth King of Rohan.", "f": [["Title", "King of Rohan"], ["Also known as", "Elfwine the Fair"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "Early Fourth Age"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Elfwine"}, "Elladan": {"s": "Elladan and Elrohir were the twin Half-elven Sons of Elrond and Celebrían of Rivendell, and were noted for their close friendship and cooperation with the Dúnedain of Arnor, Rangers of the North, and Men in general, and for their deeds during the War of the Ring.", "f": [["Title", "Sons of Elrond"], ["Race", "Half-elves"], ["Culture", "Elves of Rivendell"], ["Born", "TA 130"], ["Died", "Unknown"], ["Height", "Tall"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Played by", "Sam and Matt Kennard (Born of Hope)"]], "u": "https://lotr.fandom.com/wiki/Elladan_and_Elrohir"}, "Elmo": {"s": "Elmo was an Elf of the royal house of the Teleri. He was the younger brother of the two Kings of the Teleri, Elwë and Olwë.", "f": [["Title", "Unknown"], ["Race", "Elves"], ["Culture", "Teleri, Sindar (House of Elmo)"], ["Born", "Between YT 1105 and YT 1150"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Elmo"}, "Elphir": {"s": "Elphir was the twenty-third Prince of Dol Amroth.", "f": [["Title", "Prince of Dol Amroth"], ["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Dol Amroth)"], ["Born", "TA 2987"], ["Died", "FO 67 (aged 101)"]], "u": "https://lotr.fandom.com/wiki/Elphir"}, "Elrohir": {"s": "Elladan and Elrohir were the twin Half-elven Sons of Elrond and Celebrían of Rivendell, and were noted for their close friendship and cooperation with the Dúnedain of Arnor, Rangers of the North, and Men in general, and for their deeds during the War of the Ring.", "f": [["Title", "Sons of Elrond"], ["Race", "Half-elves"], ["Culture", "Elves of Rivendell"], ["Born", "TA 130"], ["Died", "Unknown"], ["Height", "Tall"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Played by", "Sam and Matt Kennard (Born of Hope)"]], "u": "https://lotr.fandom.com/wiki/Elladan_and_Elrohir"}, "Elrond": {"s": "Elrond was a mighty Half-elf ruler who dwelt in Middle-earth from the First Age to the beginning of the Fourth Age. He was the Lord of Rivendell and father of Elladan, Elrohir, and Arwen Undómiel, the eventual wife of Aragorn II. He was given the epithet of Peredhel, Sindarin for Half-elven.", "f": [["Title", "Lord of Rivendell;, Bearer of Vilya;, Vice-regent and herald to Gil-galad"], ["Also known as", "Elrond Peredhel, Elrond \"Half-elven\", Master Elrond"], ["Race", "Half-elf (chose to be immortal)"], ["Born", "FA 532"], ["Died", "Departed to Aman on September 29, 3021"], ["Hair", "Dark brown/Black, dark gray (aged)"], ["Eyes", "Dark gray"], ["Played by", "Hugo Weaving (LOTR films), Robert Aramayo (The Rings of Power), Andrei Tolshin (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Elrond"}, "Elros": {"s": "Elros, also known as Elros Tar-Minyatur, the Half-elven, was the son of Eärendil and Elwing, brother of Elrond, uncle of Elladan and Elrohir and Arwen, and the first King of Númenor; ancestor to a line of kings that led to his distant descendant Aragorn II. He had a strong friendship with the Elves, who were half his kin.", "f": [["Title", "King of Númenor"], ["Also known as", "Elerossë (Q.), Indilzar (A.)"], ["Race", "Half-elf (chose to be mortal)"], ["Culture", "Ñoldor (House of Fingolfin), Sindar (House of Thingol), Dúnedain of Númenor (House of Elros)"], ["Born", "FA 532"], ["Died", "SA 442 (500 Aged)"], ["Height", "Tall"], ["Hair", "Dark"], ["Eyes", "Grey"], ["Weapon", "Aranrúth, Axe of Tuor"], ["Played by", "Robert Aramayo"]], "u": "https://lotr.fandom.com/wiki/Elros"}, "Eluréd": {"s": "Eluréd and Elurín were the twin sons of Dior Eluchîl, the Half-elven son of Beren and Lúthien, and Dior's Elven wife, Nimloth.", "f": [["Race", "Half-elves"], ["Culture", "Sindar of Doriath (House of Thingol)"], ["Born", "FA 500"], ["Died", "Last seen in the forests of Doriath in FA 509"]], "u": "https://lotr.fandom.com/wiki/Elur%C3%A9d_and_Elur%C3%ADn"}, "Elurín": {"s": "Eluréd and Elurín were the twin sons of Dior Eluchîl, the Half-elven son of Beren and Lúthien, and Dior's Elven wife, Nimloth.", "f": [["Race", "Half-elves"], ["Culture", "Sindar of Doriath (House of Thingol)"], ["Born", "FA 500"], ["Died", "Last seen in the forests of Doriath in FA 509"]], "u": "https://lotr.fandom.com/wiki/Elur%C3%A9d_and_Elur%C3%ADn"}, "Elwing": {"s": "Elwing also known as Elwing the White, was the Half-elven daughter of Dior the Fair and his wife Nimloth. She was the younger sister of the twin brothers Eluréd and Elurín. She became the wife of another Half-elf, Eärendil the Mariner, and was the mother of Elrond and Elros.", "f": [["Title", "Princess of Doriath, Lady of Arvernien"], ["Also known as", "The White"], ["Race", "Half-elves (chose to be immortal)"], ["Culture", "Sindar of Doriath (House of Thingol)"], ["Born", "FA 503"], ["Height", "Tall"], ["Hair", "Dark"], ["Eyes", "Possibly grey"], ["Weapon", "Elf-magic"]], "u": "https://lotr.fandom.com/wiki/Elwing"}, "Eorl the Young": {"s": "Eorl was the last Lord of the Éothéod and the first King of Rohan. He was the founder of the House of Eorl, the royal dynasty which ruled Rohan.", "f": [["Title", "Lord of the Éothéod, King of Rohan, The Young"], ["Race", "Men"], ["Culture", "Éothéod, Rohirrim"], ["Born", "TA 2485"], ["Died", "TA 2545"], ["Hair", "Blond"], ["Weapon", "King's sword"]], "u": "https://lotr.fandom.com/wiki/Eorl_the_Young"}, "Erchirion": {"s": "Erchirion was the second son of Prince Imrahil. (His mother's name is unknown.)", "f": [["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Dol Amroth)"], ["Born", "TA 2990"], ["Died", "Early Fourth Age ?"]], "u": "https://lotr.fandom.com/wiki/Erchirion"}, "Eärendil": {"s": "Eärendil (Quenya; IPA:) was a great Half-elf mariner who voyaged to Valinor, entreated before the Valar on behalf of the Children of Ilúvatar, and carried a star across the sky at the end of the First Age. His acts had been prophesied of among the Elves centuries beforehand.", "f": [["Title", "Prince of Gondolin, Lord of Arvernien"], ["Also known as", "The Mariner, Half-elf, Bright, Blessed, Eärendel, Ardamírë, Mír n'Ardhon, Azrubêl"], ["Race", "Half-elves (chose to be immortal)"], ["Culture", "Ñoldor (Gondolindrim), Edain (House of Hador)"], ["Born", "FA 503, Gondolin"], ["Height", "Tall"], ["Hair", "Golden"], ["Eyes", "Blue"], ["Weapon", "Sword"]], "u": "https://lotr.fandom.com/wiki/E%C3%A4rendil"}, "Eärnur": {"s": "Eärnur was the thirty-third and last King of Gondor until the accession of Aragorn II Elessar. He took the throne upon the death of his father Eärnil II in TA 2043, and after his disappearance the Stewards of Gondor ruled in his name for many generations.", "f": [["Title", "King of Gondor"], ["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Anárion)"], ["Born", "TA 1928"], ["Died", "In or after TA 2050"], ["Weapon", "King's sword"]], "u": "https://lotr.fandom.com/wiki/E%C3%A4rnur"}, "Falco Chubb-Baggins": {"s": "Falco Chubb-Baggins was a Hobbit of the Shire.", "f": [["Race", "Hobbits"], ["Culture", "Shire-hobbits (Chubb-Baggins family)"], ["Born", "TA 2903 (SR 1303)"], ["Died", "TA 2999 (SR 1399)"]], "u": "https://lotr.fandom.com/wiki/Falco_Chubb-Baggins"}, "Faramir": {"s": "Faramir was the second son of Denethor II and younger brother of Boromir. He was Captain of the Rangers of Ithilien and Captain of the White Tower upon his brother's death.", "f": [["Race", "Men"], ["Culture", "Men of Gondor (House of Húrin)"], ["Born", "TA 2983"], ["Died", "February 26, FO 82 (aged 120)"], ["Hair", "\"Raven\""], ["Eyes", "Grey"], ["Weapon", "Sword, nail-knife"], ["Played by", "David Wenham"]], "u": "https://lotr.fandom.com/wiki/Faramir"}, "Faramir Took": {"s": "Faramir Took was a Hobbit of the Shire and the son of Peregrin Took and Diamond of Long Cleeve. He was also the thirty-third Shire-thain.", "f": [["Title", "Shire-thain"], ["Race", "Hobbits"], ["Culture", "Shire-folk (Took-clan)"], ["Born", "FO 10 (SR 1430)"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Faramir_Took"}, "Farin": {"s": "Farin was a Dwarf of the line of Durin's Folk.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Grey Mountains, Dwarves of the Lonely Mountain, Dwarves of Thorin's Halls"], ["Born", "TA 2560"], ["Died", "TA 2803"], ["Height", "About 4'0\" at least"], ["Weapon", "unknown, possibly a Battle-axe"]], "u": "https://lotr.fandom.com/wiki/Farin"}, "Fengel": {"s": "Fengel was the fifteenth King of Rohan.", "f": [["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2870"], ["Died", "TA 2953"]], "u": "https://lotr.fandom.com/wiki/Fengel"}, "Finarfin": {"s": "Finarfin was a Ñoldorin Elf of Valinor.", "f": [["Title", "High King of the Ñoldor (in Valinor)"], ["Also known as", "Arafinwë, Ingoldo"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finwë)"], ["Born", "YT 1230"], ["Died", "Immortal"], ["Hair", "Golden"]], "u": "https://lotr.fandom.com/wiki/Finarfin"}, "Findis": {"s": "Findis was a Ñoldorin elf, the first daughter of Finwë, the High King of the Ñoldor and Indis; sister of Fingolfin, Finarfin, and Írimë and half-sister of Fëanor.", "f": [["Race", "Elves"], ["Culture", "Ñoldor (House of Finwë)"], ["Born", "Years of the Trees, between YT 1185 and YT 1190"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Findis"}, "Fingolfin": {"s": "Fingolfin was the first High King of the Ñoldor in Beleriand. He was the eldest son of Finwë and Indis, younger brother of Findis, older brother of Irimë and Finarfin, and the younger half-brother of Fëanor. He founded the House of Fingolfin, which ruled the Ñoldor in Middle-earth.", "f": [["Title", "High King of the Ñoldor, King of Hithlum"], ["Also known as", "Ñolofinwë Arakáno"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finwë)"], ["Born", "YT 1190, Tirion"], ["Died", "FA 456, Angband"], ["Hair", "Dark"], ["Weapon", "Ringil"]], "u": "https://lotr.fandom.com/wiki/Fingolfin"}, "Fingon": {"s": "Fingon the \"Valiant\" was a Ñoldorin Elf, the eldest son of Fingolfin, and older brother of Turgon, Aredhel, and Argon.", "f": [["Title", "High King of the Ñoldor"], ["Also known as", "Findekáno, the Valiant"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fingolfin)"], ["Born", "YT 1260, Eldamar"], ["Died", "FA 472, Nírnaeth Arnoediad"], ["Height", "Tall"], ["Hair", "Dark"], ["Weapon", "Sword"]], "u": "https://lotr.fandom.com/wiki/Fingon"}, "Finrod": {"s": "Finrod, known fully as Finrod Felagund, was a Ñoldor Elf who was born in Aman. He was King of Nargothrond and the eldest son of Finarfin and Eärwen, and the brother of Galadriel, Angrod and Aegnor. Finrod was one of the noblest Elves of the House of Finarfin and a friend of Men.", "f": [["Title", "King of Nargothrond, Lord of Narog, Faithful, Friend-of-Men, Master of Caves"], ["Also known as", "Felagund, Ingoldo, Findarato/Artafinde, Nóm or Nómin, Finarfin (in earlier texts)"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finarfin), Falmari (House of Olwë), Nargothronders"], ["Born", "YT 1300"], ["Died", "FA 465, Tol-in-Gaurhoth"], ["Hair", "Golden"], ["Weapon", "Sword, bow"], ["Played by", "Will Fletcher"]], "u": "https://lotr.fandom.com/wiki/Finrod"}, "Finwë": {"s": "Finwë was the first King of the Ñoldor who led his people on the journey from Middle-earth to Valinor in the blessed realm of Aman. He was a great friend of Elu Thingol, the King of Doriath. He was the father of Fëanor, Fingolfin, Finarfin, Írimë, and Findis.", "f": [["Title", "King of the Ñoldor"], ["Also known as", "Ñoldóran"], ["Race", "Elves"], ["Culture", "Ñoldor, (House of Finwë)"], ["Born", "Between YT 1050 and 1102, Cuiviénen"], ["Died", "YT 1495, Formenos"], ["Height", "Tall"], ["Hair", "Black"], ["Eyes", "Grey"]], "u": "https://lotr.fandom.com/wiki/Finw%C3%AB"}, "Frerin": {"s": "Frerin was a Dwarf of Durin's Folk.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Lonely Mountain"], ["Born", "TA 2751"], ["Died", "TA 2799"], ["Height", "About 4'0\" at least"], ["Weapon", "Battle axe"]], "u": "https://lotr.fandom.com/wiki/Frerin"}, "Frodo Baggins": {"s": "Frodo Baggins was a Hobbit of The Shire in the late Third Age. He was a key figure in the Quest of Mount Doom, in which he bore the One Ring to Mount Doom, where it was destroyed. He was a Ring-bearer, best friend to his gardener, Samwise Gamgee, and was one of three hobbits who sailed from Middle-earth to the Uttermost West at the end of the Third Age.", "f": [["Title", "Bearer of the One Ring, Elf-friend, Deputy Mayor of Michel Delving"], ["Also known as", "Frodo of the Nine Fingers, Nine-Fingered Frodo, Maura Labingi (Westron name), Mr. Underhill, Sneaky hobbit (by Gollum)"], ["Race", "Men (Hobbits)"], ["Culture", "Shire-folk (Brandybuck family/Baggins family)"], ["Born", "September 22, TA 2968 (SR 1368)"], ["Died", "Sometime after September 29, TA 3021 (aged at least 53), Undying Lands"], ["Height", "Between 3'4\" and 3'6\""], ["Hair", "Brown"], ["Eyes", "Blue"], ["Weapon", "Sting and Barrow-blade"], ["Played by", "Elijah Wood (&), Valery Dyachenko (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Frodo_Baggins"}, "Fréaláf Hildeson": {"s": "Fréaláf Hildeson was the tenth King of Rohan, and the first king of the second line (via sister of previous king).", "f": [["Title", "King of Rohan"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2726"], ["Died", "TA 2798"], ["Weapon", "King's sword"]], "u": "https://lotr.fandom.com/wiki/Fr%C3%A9al%C3%A1f_Hildeson"}, "Frór": {"s": "Frór (TA 2552 – TA 2589) was a Dwarf of the Ered Mithrin (the Grey Mountains) and was of the line of Durin.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Grey Mountains"], ["Born", "TA 2552"], ["Died", "TA 2589"], ["Height", "About 4'0\" at least}}"], ["Played by", "Brett Beattie"]], "u": "https://lotr.fandom.com/wiki/Fr%C3%B3r"}, "Fundin": {"s": "Fundin was the son of Farin, the brother of Gróin, father of Balin and Dwalin, and uncle of Óin and Glóin, four of Thorin II Oakenshield's companions in the Quest of Erebor.", "f": [], "u": "https://lotr.fandom.com/wiki/Fundin"}, "Fëanor": {"s": "Fëanor was a Ñoldorin Elf, second King of the Noldor. It was he who led his people from Valinor in pursuit of Morgoth after the latter destroyed the Two Trees of Valinor and stole the Silmarils.", "f": [["Title", "King of the Ñoldor, Lord of the Lights"], ["Also known as", "Curufinwë, Fëanáro"], ["Race", "Elves"], ["Culture", "Ñoldor, (House of Finwë)"], ["Born", "YT 1169, Valinor"], ["Died", "YT 1497, Battle Under the Stars"], ["Height", "Tall"], ["Hair", "Raven-dark"], ["Weapon", "Elven sword"]], "u": "https://lotr.fandom.com/wiki/F%C3%ABanor"}, "Fíli": {"s": "Fíli and Kíli were Dwarven brothers and were also the youngest of the thirteen Dwarves who set out with Thorin Oakenshield's company, along with Gandalf and Bilbo Baggins, to reclaim the Lonely Mountain from the dragon Smaug.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2859 (Fíli), TA 2864 (Kíli)"], ["Died", "November 23, TA 2941 (Fíli aged 82 and Kíli aged 77), Battle of Five Armies"], ["Hair", "Yellow"], ["Played by", "Dean O'Gorman (Fíli), Aidan Turner (Kíli)"]], "u": "https://lotr.fandom.com/wiki/F%C3%ADli_and_K%C3%ADli"}, "Galadhon": {"s": "Galadhon was a noble Sindar Elf of Doriath, the son of Elmo, the younger brother of Elwë (Thingol) and Olwë. Little is known about him, save that he was the father of Celeborn and Galathil, father of Nimloth.", "f": [["Race", "Elves"], ["Culture", "Sindar (House of Elmo), Elves of Doriath"]], "u": "https://lotr.fandom.com/wiki/Galadhon"}, "Galadriel": {"s": "Galadriel was the Ñoldorin Lady of the woods of Lothlórien who witnessed Middle-earth during the three Ages of Awakening.", "f": [["Title", "Princess of the Ñoldor, Lady of Lórien, Lady of the Wood, Lady of the Galadhrim, Mistress of Magic"], ["Also known as", "Alatáriel, Artanis, Nerwen"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finarfin)"], ["Born", "YT 1362"], ["Died", "Departed to Valinor on, September 29, 3021"], ["Height", "6' 4\""], ["Hair", "Radiant gold touched with silver"], ["Weapon", "Nenya (ring), elf-magic"], ["Played by", "Cate Blanchett, Amelie Child-Villiers, Morfydd Clark, Elena Solovey (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Galadriel"}, "Galathil": {"s": "Galathil was a Sindarin elf of Doriath.", "f": [["Race", "Elves"], ["Culture", "Sindar (Elves of Doriath)"]], "u": "https://lotr.fandom.com/wiki/Galathil"}, "Gerontius Took": {"s": "Gerontius Took, more commonly known as the Old Took, was a Hobbit of the Shire, and the twenty-sixth Shire-thain. He was best known for being the third oldest hobbit in Middle-earth's history, living to the advanced age of 130 years. Only his grandson Bilbo Baggins and the Stoor Sméagol, whose lifetimes were prolonged by the powers of the One Ring, lived longer.", "f": [["Title", "Shire-thain"], ["Also known as", "The Old Took"], ["Race", "Hobbits"], ["Culture", "Shire-folk (Took-clan)"], ["Born", "TA 2790 (SR 1190)"], ["Died", "TA 2920 (SR 1320)"], ["Played by", "Dan Hennah"]], "u": "https://lotr.fandom.com/wiki/Gerontius_Took"}, "Gil-galad": {"s": "Ereinion Gil-galad, born Artanáro, was a Ñoldorin Elf and son to Orodreth. He was the last Ñoldóran in Middle-earth, and bore many titles, including High King of the Elves of the West, King of the Eldar (to some), King of Lindon, Lord of the High Elves (largely because most of them remaining are Ñoldor), and the Lord of Eriador.", "f": [["Title", "Ñoldóran, King of the High Elves"], ["Also known as", "Ereinion, Artanáro, Rodnor, Finellach, Finwain"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finarfin)"], ["Born", "YT 1481, Eldamar"], ["Died", "SA 3441 (aged 4,213), Siege of Barad-dûr"], ["Hair", "Silver"], ["Weapon", "Aeglos (spear), Vilya (one of the Three Rings)"], ["Played by", "Mark Ferguson, Benjamin Walker"]], "u": "https://lotr.fandom.com/wiki/Gil-galad"}, "Gimli": {"s": "Gimli, son of Glóin, was a Dwarf of the House of Durin and a member of the Fellowship of the Ring. Unlike other Dwarves, he readily fought alongside Elves in the War of the Ring against Sauron at the end of the Third Age. After the defeat of Sauron, in the early Fourth Age, he was given the lordship over the Glittering Caves at Helm's Deep, which he presided over until he departed from Middle-earth.", "f": [["Title", "Lord of the Glittering Caves"], ["Also known as", "Elf-friend, Lockbearer"], ["Race", "Dwarves"], ["Culture", "Longbeards"], ["Born", "TA 2879"], ["Died", "Departed to Aman in FO 120 from Ithilien (aged at least 262)"], ["Height", "About 4'0\" at least"], ["Hair", "Red"], ["Eyes", "Dark"], ["Weapon", "Broad-bladed axe"], ["Played by", "John Rhys-Davies"]], "u": "https://lotr.fandom.com/wiki/Gimli"}, "Glóin": {"s": "Glóin, son of Gróin, was one of the Dwarves of Thorin II Oakenshield's company who set out to reclaim the Lonely Mountain in the Quest of Erebor. He was also the father of Gimli, who became a member of the Fellowship of the Ring.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Lonely Mountain"], ["Born", "TA 2783"], ["Died", "FO 15"], ["Height", "About 4'0\" at least"], ["Hair", "White"], ["Weapon", "Axe"], ["Played by", "Peter Hambleton, John Rhys-Davies"]], "u": "https://lotr.fandom.com/wiki/Gl%C3%B3in"}, "Gróin": {"s": "Gróin was the son of Farin, was a Dwarf of Durin's Folk, brother of Fundin, and father of Óin and Glóin.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2671"], ["Died", "TA 2923"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/Gr%C3%B3in"}, "Grór": {"s": "Grór was the founder of the Dwarven settlements in the Iron Hills and their first lord.", "f": [["Title", "Lord of the Iron Hills"], ["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Iron Hills"], ["Born", "TA 2563"], ["Died", "TA 2805 (aged 242)"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/Gr%C3%B3r"}, "Hamfast Gamgee": {"s": "Hamfast \"The Gaffer\" Gamgee was a Hobbit of the Shire, a gardener by trade and father of Samwise Gamgee.", "f": [["Also known as", "The Gaffer, Ranugad Galbasi"], ["Race", "Hobbit"], ["Culture", "Shire-hobbits"], ["Born", "TA 2926 (SR 1326)"], ["Died", "FO 7 (SR 1428)"], ["Height", "3'0\"-4'0\""], ["Hair", "Brown, later gray"], ["Played by", "Norman Forsey"]], "u": "https://lotr.fandom.com/wiki/Hamfast_Gamgee"}, "Húrin of Emyn Arnen": {"s": "Húrin of Emyn Arnen was a nobleman of Gondor, the first known Steward to the King of Gondor, and an ancestor of the Ruling Stewards of Gondor.", "f": [["Title", "Steward to the King of Gondor"], ["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Húrin)"], ["Born", "Mid-Third Age ?"], ["Died", "Mid-Third Age ?"]], "u": "https://lotr.fandom.com/wiki/H%C3%BArin_of_Emyn_Arnen"}, "Idril": {"s": "Idril, also called Celebrindal, was a Ñoldorin Elf of Gondolin. She was the daughter of Turgon and Elenwë, wife of the Man Tuor, and mother of Eärendil the Mariner, a Half-elven.", "f": [["Title", "Princess of Gondolin, Lady of Arvernien"], ["Also known as", "Celebrindal, Itaril, Itarillë, Itarildë"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fingolfin), Gondolindrim"], ["Born", "YT 1479"], ["Died", "FA 525 (sailed West)"], ["Height", "Tall"], ["Hair", "Golden"], ["Weapon", "A sword"]], "u": "https://lotr.fandom.com/wiki/Idril"}, "Imrahil": {"s": "Imrahil, also known as Prince Imrahil, was the twenty-second Prince of Dol Amroth. He had two older sisters, Ivriniel and Finduilas. His daughter Lothíriel wedded Éomer, King of Rohan, in the last year of the Third Age.", "f": [["Title", "Prince of Dol Amroth"], ["Also known as", "Imrahil the Fair"], ["Race", "Men"], ["Culture", "Dúnedain (House of Dol Amroth), Men of Gondor"], ["Born", "TA 2955"], ["Died", "FO 34"], ["Height", "Tall"], ["Hair", "Black"], ["Eyes", "Grey"], ["Weapon", "Sword, lance"]], "u": "https://lotr.fandom.com/wiki/Imrahil"}, "Isengar": {"s": "Isengar Took was a Hobbit of the Shire and one of the many uncles of Bilbo Baggins.", "f": [["Race", "Hobbits"], ["Culture", "Shire-hobbits (Tooks)"], ["Born", "TA 2862 (SR 1262)"], ["Died", "TA 2960 (SR 1360)"]], "u": "https://lotr.fandom.com/wiki/Isengar_Took"}, "Isildur": {"s": "Isildur was the oldest son of Elendil and the brother of Anárion. He and Anárion founded and jointly ruled Gondor in the south, while their father dwelt in Arnor in the north.", "f": [["Title", "King of Gondor, High King of Arnor and, Gondor, High King of the Dúnedain"], ["Race", "Men"], ["Born", "SA 3209"], ["Died", "TA 2, Disaster of the Gladden Fields"], ["Height", "7'0\""], ["Played by", "Harry Sinclair, Maxim Baldry"]], "u": "https://lotr.fandom.com/wiki/Isildur"}, "Kíli": {"s": "Fíli and Kíli were Dwarven brothers and were also the youngest of the thirteen Dwarves who set out with Thorin Oakenshield's company, along with Gandalf and Bilbo Baggins, to reclaim the Lonely Mountain from the dragon Smaug.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2859 (Fíli), TA 2864 (Kíli)"], ["Died", "November 23, TA 2941 (Fíli aged 82 and Kíli aged 77), Battle of Five Armies"], ["Hair", "Yellow"], ["Played by", "Dean O'Gorman (Fíli), Aidan Turner (Kíli)"]], "u": "https://lotr.fandom.com/wiki/F%C3%ADli_and_K%C3%ADli"}, "Legolas": {"s": "Legolas was a Sindar Elf who joined the Fellowship of the Ring in the Third Age. Son of the Elvenking Thranduil of Mirkwood, Legolas was Mirkwood's prince, a messenger, and a master archer. With his keen eyesight, sensitive hearing, and excellent bowmanship, Legolas was valuable to the Fellowship in their journey across Middle-earth.", "f": [["Title", "Prince of the Woodland Realm"], ["Also known as", "Greenleaf"], ["Race", "Elves"], ["Culture", "Sindar (Elves of Mirkwood)"], ["Died", "Departed to Aman in FO 120 from Ithilien"], ["Height", "At least 6'0\""], ["Weapon", "Bow and \"long white knife\""], ["Played by", "Orlando Bloom ; Olga Serebryakova, (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Legolas"}, "Lotho Sackville-Baggins": {"s": "Lotho Sackville-Baggins was a Hobbit of the Shire, hailing from the Sackville-Baggins family.", "f": [["Title", "Chief Shirriff"], ["Also known as", "Little Pimple, Pimple, The Boss, The Chief"], ["Race", "Hobbits"], ["Culture", "Shire-folk (Sackville-Baggins)"], ["Born", "TA 2964 (SR 1364)"], ["Died", "Between September 22-November 2 TA 3019 (SR 1419)"], ["Hair", "Sandy"]], "u": "https://lotr.fandom.com/wiki/Lotho_Sackville-Baggins"}, "Lothíriel": {"s": "Lothíriel was a princess of Dol Amroth in Middle-earth, daughter of Prince Imrahil, and later Queen of Rohan.", "f": [["Title", "Princess of Dol, Amroth, Queen of Rohan"], ["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Dol Amroth), Rohirrim"], ["Born", "TA 2999"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Loth%C3%ADriel"}, "Lúthien": {"s": "Lúthien, also known as Tinúviel, was the immortal princess of Doriath, wife of Beren Erchamion, and the most beautiful of all the Children of Ilúvatar to ever live. Her love of the mortal man Beren, for whom she was prepared to risk everything, including her life, was legendary and lamented forever in song and story. She and Beren braved Morgoth's horrors, eventually winning a Silmaril from his crown and the approval of their marriage by King Thingol.", "f": [["Title", "Princess of Doriath, Lady of Tol Galen"], ["Also known as", "Tinúviel"], ["Race", "Half Elf, half Maia"], ["Culture", "Sindar of Doriath (House of Thingol)"], ["Born", "YT 1200"], ["Died", "FA 467/FA 503 (aged 3,342/3,378)"], ["Height", "Tall"], ["Hair", "Dark brown"], ["Eyes", "Grey"], ["Weapon", "Elf-magic, voice"]], "u": "https://lotr.fandom.com/wiki/L%C3%BAthien"}, "Maedhros": {"s": "Maedhros, also called Maedhros the Tall, was a prince of the Ñoldor, eldest of the seven Sons of Fëanor, and head of the House of Fëanor following the death of his father in Middle-earth. He was highly renowned for his skills as warrior and diplomat. For centuries, he led his House against the forces of Morgoth, but the Oath that he and his six brothers had sworn to recover the Silmarils constrained him and ultimately brought his demise.", "f": [["Title", "Prince of the Ñoldor, High King of the Ñoldor, (abdicated), Lord of the House of Fëanor, Lord of Himring or the March of Maedhros"], ["Also known as", "Maedhros the Tall, Maedhros the Dispossessed, Nelyafinwë, Nelyo, Maitimo, Russandol, Maidros"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "During the, Noontide of Valinor"], ["Died", "FA 587"], ["Height", "Over 6' 5\""], ["Hair", "Dark red"], ["Weapon", "Elven sword"]], "u": "https://lotr.fandom.com/wiki/Maedhros"}, "Maeglin": {"s": "Maeglin was an Elf, the son of Eöl the \"Dark Elf\" and Aredhel, daughter of Fingolfin. He lived during the First Age of the Sun in Middle-earth, and was a lord of the hidden Elven kingdom of Gondolin. He became infamous for his betrayal of the location of Gondolin to the Dark Lord Morgoth.", "f": [["Title", "Lord of the Mole"], ["Also known as", "Lómion"], ["Race", "Elves"], ["Culture", "Avari (Moriquendi), Ñoldor (House of Fingolfin), Gondolindrim (House of the Mole)"], ["Born", "FA 320"], ["Died", "FA 510, Battle of Gondolin"], ["Height", "Tall"], ["Hair", "Black"], ["Eyes", "Dark"], ["Weapon", "Anguirel"]], "u": "https://lotr.fandom.com/wiki/Maeglin"}, "Maglor": {"s": "Maglor was the second son of Fëanor and Nerdanel. He was the greatest poet and minstrel of the Ñoldor and was said to have inherited his mother's gentler temperament.", "f": [["Title", "Lord of Maglor's Gap"], ["Also known as", "Macalaurë, Canafinwë, Káno"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fëanor)"], ["Born", "During the Noontide of Valinor"], ["Died", "Fate unknown; last mentioned in FA 587"], ["Height", "Shorter than Maedhros"], ["Hair", "Dark brown or black"], ["Eyes", "Grey"]], "u": "https://lotr.fandom.com/wiki/Maglor"}, "Meneldil": {"s": "Meneldil was the third King of Gondor (his father Anárion and uncle Isildur co-ruled Gondor as the second kings, but his father died before Isildur who was sole ruler for a short time).", "f": [["Title", "King of Gondor"], ["Race", "Men"], ["Culture", "Dúnedain, Men of Gondor (House of Anárion)"], ["Born", "SA 3318"], ["Died", "TA 158"], ["Weapon", "King's sword"]], "u": "https://lotr.fandom.com/wiki/Meneldil"}, "Meriadoc Brandybuck": {"s": "Meriadoc \"Merry\" Brandybuck was a Hobbit of the Shire and one of Frodo Baggins cousins and closest friends. He loved boats and ponies and had a great interest in the maps of Middle-earth. He was also one of the nine companions of the The Fellowship of the Ring, and later became the eighth Master of Buckland.", "f": [["Title", "Master of Buckland, Knight of Rohan"], ["Also known as", "Merry, \"the Magnificent\", Kalimac \"Kali\" Brandagamba, Holdwine of the Shire"], ["Race", "Hobbit"], ["Culture", "Shire-hobbits, Bucklanders (Brandybuck family)"], ["Born", "TA 2982/SR 1382"], ["Died", "After FO 63/SR 1484 (aged 102+), Gondor"], ["Height", "Between 3'4\" and 3'6\" (before drinking ent-draughts), At least 4'6\" (after drinking ent-draughts)"], ["Hair", "Brown, curly"], ["Weapon", "Dagger of Westernesse"], ["Played by", "Dominic Monaghan, Sergey Shelgunov (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Meriadoc_Brandybuck"}, "Nimloth": {"s": "Nimloth was an Elf of Doriath during the First Age. She was the daughter of Galathil, son of Galadhon, the son of Elmo. Elmo was the brother of Olwë and Elwë, making her a kinswoman of King Thingol.", "f": [["Title", "Queen of Doriath"], ["Also known as", "Lady Lindis"], ["Race", "Elves"], ["Culture", "Sindar (House of Elmo), Elves of Doriath"], ["Born", "Unknown, possibly sometime during the Years of the Trees"], ["Died", "FA 506"]], "u": "https://lotr.fandom.com/wiki/Nimloth_of_Doriath"}, "Nori": {"s": "Nori was a Dwarf of Durin's Folk. He had a brother named Dori and a cousin named Ori, and was a remote kinsman of Thorin Oakenshield.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Weapon", "Axe|height=About 4'0\"}}"], ["Played by", "Jed Brophy"]], "u": "https://lotr.fandom.com/wiki/Nori"}, "Náin": {"s": "Náin was the name of the following Dwarves, two of which were Kings of Durin's Folk.", "f": [], "u": "https://lotr.fandom.com/wiki/N%C3%A1in_%28disambiguation%29"}, "Náin II": {"s": "Náin II was a Dwarf of the Ered Mithrin, and the King of Durin's Folk.", "f": [["Title", "King of Durin's Folk"], ["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Grey Mountains"], ["Born", "TA 2338"], ["Died", "TA 2585"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/N%C3%A1in_II"}, "Odo Proudfoot": {"s": "Odo Proudfoot was a Hobbit of the Shire, and a cousin of Bilbo Baggins. He characteristically had exceptionally large and hairy feet.", "f": [["Race", "Hobbits"], ["Culture", "Shire-hobbit (Proudfoot family)"], ["Born", "TA 2904 (SR 1304)"], ["Died", "TA 3005 (SR 1405)"], ["Played by", "Noel Appleby"]], "u": "https://lotr.fandom.com/wiki/Odo_Proudfoot"}, "Ori": {"s": "Ori was a member of Thorin's Company of Dwarves who participated in the Quest of Erebor and the Battle of Five Armies, which he survived. He and his brothers, Dori and Nori, were remote kinsmen of Thorin II Oakenshield.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of the Northern Blue Mountains, Dwarves of the Lonely Mountain"], ["Died", "TA 2994, Chamber of Mazarbul"], ["Height", "About 4'0\" at least"], ["Played by", "Adam Brown}}"]], "u": "https://lotr.fandom.com/wiki/Ori"}, "Orodreth": {"s": "Orodreth was a Ñoldorin Elf of the First Age who was the second ruler of the underground city of Nargothrond in western Beleriand. He was later killed in the Battle of Tumhalad.", "f": [["Title", "Warden of Minas Tirith, King of Nargothrond"], ["Also known as", "Artaher, Arothir, Artaresto"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Finarfin), Falmari (House of Olwë), Elves of Nargothrond"], ["Born", "YT?"], ["Died", "FA 495, Battle of Tumhalad"], ["Hair", "Golden"], ["Weapon", "Sword, bow"]], "u": "https://lotr.fandom.com/wiki/Orodreth"}, "Oropher": {"s": "Oropher was the Sindar King of the Silvan Elves of Greenwood the Great during the Second Age. He was the father of Thranduil, who would succeed him, and grandfather of Legolas.", "f": [["Title", "Lord of Northern Mirkwood, King of the Silvan Elves, King of the Woodland Realm"], ["Race", "Elves"], ["Culture", "Sindar (Elves of Doriath)"], ["Born", "First Age"], ["Died", "SA 3434"]], "u": "https://lotr.fandom.com/wiki/Oropher"}, "Otho Sackville-Baggins": {"s": "Otho Sackville-Baggins was a Hobbit of the Shire.", "f": [["Race", "Hobbits"], ["Culture", "Shire-hobbits (Sackville-Baggins)"], ["Born", "TA 2910 (SR 1309)"], ["Died", "TA 3012 (SR 1411)"], ["Height", "1.22m (4'0\")"], ["Played by", "Peter Corrigan, (The Lord of the Rings), Brian Hotter, (The Hobbit trilogy)"]], "u": "https://lotr.fandom.com/wiki/Otho_Sackville-Baggins"}, "Peregrin Took": {"s": "Peregrin Took, more commonly known as Pippin, was a hobbit of The Shire and one of Frodo Baggins's youngest and closest friends. He was a member of the Fellowship of the Ring and, after the War of the Ring, became the thirty-second Shire-thain.", "f": [["Title", "Shire-thain, Guard of the Citadel, Knight of Gondor"], ["Also known as", "Pippin, Razanur Tûk, (Westron name), Ernil i Pheriannath, Thain Peregrin I, Fool of a Took"], ["Race", "Hobbits"], ["Culture", "Shire-folk (Took-clan)"], ["Born", "Spring TA 2990/SR 1390"], ["Died", "After FO 63/SR 1484 (aged 94+), Gondor"], ["Height", "3'4\" (before drinking ent-draughts), At least 4'6\" (after drinking ent-draughts)"], ["Hair", "Almost golden"], ["Weapon", "Dagger of Westernesse"], ["Played by", "Billy Boyd, Vadim Nikitin (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Peregrin_Took"}, "Samwise Gamgee": {"s": "Samwise Gamgee, also known as Samwise Gardner or simply as Sam, was a hobbit of The Shire. He was Frodo Baggins' gardener and best friend. Sam proved himself to be Frodo's closest and most dependable companion, the most loyal of the Fellowship of the Ring, and played a critical role in protecting Frodo and destroying the One Ring.", "f": [["Title", "Mayor of Michel Delving"], ["Also known as", "Sam, Perhael, Banazîr Galbasi, Samwise Gardner"], ["Race", "Hobbits"], ["Culture", "Shire-hobbits (Gamgee family)"], ["Born", "April 6, TA 2980/SR 1380"], ["Died", "In or after FO 61 (aged at least 102), Undying Lands"], ["Height", "3'4\""], ["Eyes", "Brown"], ["Weapon", "Dagger of Westernesse, also Sting (briefly)"], ["Played by", "Sean Astin (live-action films), Vladimir Matveev (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Samwise_Gamgee"}, "Silmariën": {"s": "Silmariën was a princess of Númenór known as the ancestor of the Lords of Andúnië, and receiver of many heirlooms passed to her descendants.", "f": [["Race", "Men"], ["Culture", "Númenóreans (House of Elros)"], ["Born", "SA 521"], ["Died", "Unknown"]], "u": "https://lotr.fandom.com/wiki/Silmari%C3%ABn"}, "Tar-Elendil": {"s": "Tar-Elendil was the fourth King of Númenor, succeeding his father Tar-Amandil. He was considered to be a master of lore and a notable scholar.", "f": [["Title", "King of Númenor"], ["Also known as", "Parmaitë"], ["Race", "Men"], ["Culture", "Númenóreans (House of Elros)"], ["Born", "SA 350"], ["Died", "SA 751"], ["Weapon", "Aranrúth"]], "u": "https://lotr.fandom.com/wiki/Tar-Elendil"}, "Tar-Meneldur": {"s": "Tar-Meneldur, also known as Elentirmo and Irimon, was the fifth King of Númenor. His two older sisters were Silmariën and Isilmë. During his time the Númenóreans began to return to Middle-earth, and great fleets of ships were built to explore all the lands east of Númenor.", "f": [["Title", "King of Númenor"], ["Also known as", "Elentirmo, Irimon"], ["Race", "Men"], ["Culture", "Númenóreans (House of Elros)"], ["Born", "SA 543"], ["Died", "SA 942"], ["Weapon", "Aranrúth"]], "u": "https://lotr.fandom.com/wiki/Tar-Meneldur"}, "Thengel": {"s": "Thengel was the sixteenth King of Rohan.", "f": [["Title", "King of Rohan"], ["Also known as", "The Thrice-renowned"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2905"], ["Died", "TA 2980"], ["Weapon", "King's sword"]], "u": "https://lotr.fandom.com/wiki/Thengel"}, "Thingol": {"s": "Elu Thingol, originally Elwë, was an Elf of the Teleri during the First Age. His brother was Olwë, who became the Lord of Alqualondë, Lord of Tol Eressëa, and King of the Teleri of Aman; they may have also had a second brother called Elmo, whom was a good friend of Finwë, the first King of the Ñoldor during the times before the Elves reached Aman.", "f": [["Title", "King of the Teleri, King of Doriath, Lord of Beleriand"], ["Also known as", "Elwë, Tinwelint, Singollo, Sindacollo, Sindicollo (\"Greymantle\")"], ["Race", "Elves"], ["Culture", "Teleri, Sindar of Doriath (House of Thingol)"], ["Born", "Between YT 1050 and 1102, Cuiviénen"], ["Died", "FA 503 (aged ±4566), Menegroth, killed by the Dwarves"], ["Height", "Tallest of all the Eruhíni"], ["Hair", "Silver"], ["Eyes", "Possibly grey"], ["Weapon", "Aranrúth"]], "u": "https://lotr.fandom.com/wiki/Thingol"}, "Thorin II": {"s": "Thorin II \"Oakenshield\", eventually called King under the Mountain or Mountain King, was the son of Thráin II, the older brother of Frerin and Dís, the grandson of King Thrór and the uncle of Fíli and Kíli. Thorin was best known for his deeds as leader of a company that infiltrated the lost Kingdom under the Mountain to take it back from Smaug and for leading an alliance of Men, Dwarves, and Elves in the Battle of Five Armies.", "f": [], "u": "https://lotr.fandom.com/wiki/Thorin_II"}, "Thorin III Stonehelm": {"s": "Thorin III \"Stonehelm\" was the son and heir of Dáin II of Durin's Folk, who was king of the Dwarves of Erebor and the Iron Hills in Rhovanion.", "f": [["Title", "Stonehelm, King of Durin's Folk, King under the Mountain"], ["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2866"], ["Died", "Early Fourth Age"], ["Height", "About 4'0\" at least}}"]], "u": "https://lotr.fandom.com/wiki/Thorin_III"}, "Thranduil": {"s": "Thranduil, son of Oropher, was an Elven king who ruled over the Woodland Realm in the Third Age. Though inherently cautious, his army was key to victory in the Battle of Five Armies and he defended his realm against the forces of Sauron in the War of the Ring. He was the father of the Elven prince of Mirkwood, Legolas, who was a member of the Fellowship of the Ring.", "f": [["Title", "King of the Woodland Realm"], ["Also known as", "Elvenking"], ["Race", "Elves"], ["Culture", "Sindar (Elves of Mirkwood)"], ["Born", "Before FA 506"], ["Died", "Unknown"], ["Hair", "Golden"], ["Weapon", "Sword"], ["Played by", "Lee Pace"]], "u": "https://lotr.fandom.com/wiki/Thranduil"}, "Thráin I": {"s": "Thráin I, also known as Thráin the Old, was the son of Náin I and King of Durin's Folk, as well as the first King under the Mountain.", "f": [["Title", "King of Durin's Folk, King under the Mountain"], ["Also known as", "Thráin the Old"], ["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of Lonely Mountain"], ["Born", "TA 1934"], ["Died", "TA 2190"], ["Height", "About 4'0\" at least"]], "u": "https://lotr.fandom.com/wiki/Thr%C3%A1in_I"}, "Thráin II": {"s": "Thráin II was the father of Thorin II, and the son of King Thrór, making him a direct descendant of Durin the Deathless. After his father Thrór was beheaded by Azog in Moria, Thráin became the rightful King under the Mountain as well as the King of Durin's Folk.", "f": [], "u": "https://lotr.fandom.com/wiki/Thr%C3%A1in_II"}, "Thrór": {"s": "Thrór I was the King of Durin's Folk, the son of Dáin I and brother of Frór and Grór, known for ruling Erebor, the Lonely Mountain. He was the father of Thráin II, whose son was Thorin II.", "f": [["Title", "King of Durin's Folk, King under the Mountain"], ["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "TA 2542"], ["Died", "TA 2790 (aged 248)"], ["Height", "About 4'0\" at least"], ["Played by", "Jeffrey Thomas"]], "u": "https://lotr.fandom.com/wiki/Thr%C3%B3r"}, "Théoden": {"s": "Théoden, son of Thengel and Morwen Steelsheen, was the seventeenth King of Rohan, last of the Second Line of the royal House of Eorl.", "f": [["Title", "King of Rohan, Lord of the Mark, Horsemaster, Father of Horse-men"], ["Also known as", "Théoden Ednew"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2948, Gondor"], ["Died", "March 15, 3019 (aged 71), Battle of the Pelennor Fields"], ["Hair", "White with braids"], ["Eyes", "Blue"], ["Weapon", "Herugrim"], ["Played by", "Bernard Hill"]], "u": "https://lotr.fandom.com/wiki/Th%C3%A9oden"}, "Théodred": {"s": "Théodred was a Prince of Rohan, the only son and heir of King Théoden, who perished in battle during the time Théoden was under Saruman's spell in the late Third Age.", "f": [["Title", "Second Marshal of Rohan, Prince of Rohan"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2978"], ["Died", "February 25, 3019 (aged 41)"], ["Weapon", "Sword"], ["Played by", "Paris Howe Strewe"]], "u": "https://lotr.fandom.com/wiki/Th%C3%A9odred"}, "Théodwyn": {"s": "Théodwyn of Rohan was the mother of Éomer and Éowyn.", "f": [["Title", "Princess of Rohan"], ["Race", "Men"], ["Culture", "Rohan"], ["Born", "TA 2963"], ["Died", "TA 3002"]], "u": "https://lotr.fandom.com/wiki/Th%C3%A9odwyn"}, "Tuor": {"s": "Tuor was an Adan of the House of Hador and a great hero of Men; the only son of Huor and Rían. He was the cousin of Túrin Turambar.", "f": [["Title", "Lord of the House of the Wing, Lord of Arvernien"], ["Also known as", "Tûr, Eladar (\"Starfather\"), Ulmondil (\"Friend of Ulmo\")"], ["Race", "Men"], ["Culture", "Edain (House of Hador), Eldar, Gondolindrim"], ["Born", "FA 472"], ["Died", "FA 525 (sailed West; aged 53)"], ["Height", "Tallest of all the Edain"], ["Hair", "Golden"], ["Weapon", "Dramborleg, sword"]], "u": "https://lotr.fandom.com/wiki/Tuor"}, "Turgon": {"s": "Turgon was a Ñoldor Elf of Gondolin, second son of Fingolfin, brother of Fingon, Aredhel, Argon, and father of Idril. In Middle-earth, Turgon was the King of Gondolin and became the High King of the Ñoldor after the death of his older brother Fingon. For centuries of the late First Age, Turgon remained successfully hidden from Morgoth until a betrayal by Maeglin, one of his subjects, caused its downfall.", "f": [["Title", "Lord of Nevrast, King of Gondolin, High King of the Ñoldor"], ["Also known as", "Turukáno, the Wise"], ["Race", "Elves"], ["Culture", "Ñoldor (House of Fingolfin), Gondolindrim"], ["Born", "YT 1300"], ["Died", "FA 510, Battle of Gondolin"], ["Hair", "Dark"], ["Weapon", "Glamdring"]], "u": "https://lotr.fandom.com/wiki/Turgon"}, "Valandil": {"s": "Valandil was the third High King of Arnor.", "f": [["Title", "High King of Arnor"], ["Race", "Men"], ["Culture", "Dúnedain of the North (House of Isildur)"], ["Born", "SA 3430"], ["Died", "TA 249"], ["Weapon", "King's sword"]], "u": "https://lotr.fandom.com/wiki/Valandil"}, "Vardamir Nólimon": {"s": "Vardamir Nólimon was the eldest child of Elros Tar-Minyatur, and second King of Númenor. Elrond Half-elven was his uncle. Vardamir may have been a Half-elf, with slow maturity like the Elves and ability to choose a mortal or immortal fate.", "f": [["Title", "King of Númenor"], ["Race", "Half-elves (potentially) Mortal fate"], ["Culture", "Númenóreans (House of Elros)"], ["Born", "SA 61"], ["Died", "SA 471"], ["Weapon", "Aranrúth"]], "u": "https://lotr.fandom.com/wiki/Vardamir_N%C3%B3limon"}, "Éomer": {"s": "Éomer Éadig was a man of Rohan and the eventual eighteenth King of Rohan, and first of the Third Line of their Kings. In the last decade of the Third Age, Éomer was the Third Marshal of the Mark.", "f": [["Title", "Third Marshal of the Riddermark, Lord of the Mark, King of Rohan"], ["Also known as", "Éomer Éadig"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2991"], ["Died", "FO 63"], ["Height", "6'6\""], ["Weapon", "Gúthwinë"], ["Played by", "Karl Urban"]], "u": "https://lotr.fandom.com/wiki/%C3%89omer"}, "Éowyn": {"s": "Éowyn was a shieldmaiden of Rohan, daughter of Éomund and Théodwyn, younger sister of Éomer and niece of King Théoden. After the War of the Ring, she married Faramir and had one son with him, Elboron.", "f": [["Title", "White Lady of, Rohan, Shieldmaiden of Rohan, Lady of the Shield-arm, Lady of Ithilien, Lady of Emyn Arnen"], ["Also known as", "Dernhelm"], ["Race", "Men"], ["Culture", "Rohirrim (House of Eorl)"], ["Born", "TA 2995"], ["Died", "Early Fourth Age"], ["Hair", "Pale gold"], ["Eyes", "Grey"], ["Played by", "Miranda Otto"]], "u": "https://lotr.fandom.com/wiki/%C3%89owyn"}, "Óin": {"s": "Óin (or Oin) was a dwarf of Durin's Folk known for being a part of Thorin's Company in the Quest of Erebor.", "f": [["Race", "Dwarves"], ["Culture", "Durin's Folk, Dwarves of Thorin's hall, Dwarves of the Lonely Mountain, Dwarves of Moria (briefly)"], ["Born", "TA 2774"], ["Died", "On or after TA 2994 (aged 220), Doors of Durin"], ["Height", "About 4'0\" at least|siblings=Glóin|hair=Grey|realms=Erebor, Moria}}"], ["Played by", "John Callen"]], "u": "https://lotr.fandom.com/wiki/%C3%93in"}, "Arondir": {"s": "Arondir was a Silvan Elf of the Second Age.", "f": [], "u": "https://lotr.fandom.com/wiki/Arondir"}, "Adar": {"s": "Adar was a mysterious individual of the Second Age referred to as Lord-father by Orcs, presumably for his status as one of the Moriondor, the first Elves to be captured and tortured by Morgoth.", "f": [], "u": "https://lotr.fandom.com/wiki/Adar"}, "Halbrand": {"s": "Sauron (Quenya; or), the eponymous Lord of the Rings, was the greatest fallen Maia, a former renowned disciple of Aulë, the chief agent of the first Dark Lord Morgoth in the Elder Days (First Age), the second Dark Lord, the maker of the One Ring, and self-proclaimed ruler of Middle-earth in the Second Age and near the end of the Third Age.", "f": [["Title", "Dark Lord, Lord of the Rings, Lord of the Earth, King of Men, See more"], ["Also known as", "Mairon, Annatar, Gorthaur, the Necromancer, the One Enemy, See more"], ["Race", "Ainur (Maiar)"], ["Culture", "Maia of Morgoth, (initially of Aulë)"], ["Born", "Before the Ainulindalë"], ["Died", "March 25, TA 3019, Battle of the Morannon Notice: Sauron didn't actually die, he was stripped of physical form"], ["Height", "Variable until SA 3319, (physical body)"], ["Weapon", "Powers of the Maiar, the One Ring, dark sorcery, mace, sword"], ["Played by", "Sala Baker, Charlie Vickers, Jack Lowden (prologue)"]], "u": "https://lotr.fandom.com/wiki/Sauron"}, "Sauron": {"s": "Sauron (Quenya; or), the eponymous Lord of the Rings, was the greatest fallen Maia, a former renowned disciple of Aulë, the chief agent of the first Dark Lord Morgoth in the Elder Days (First Age), the second Dark Lord, the maker of the One Ring, and self-proclaimed ruler of Middle-earth in the Second Age and near the end of the Third Age.", "f": [["Title", "Dark Lord, Lord of the Rings, Lord of the Earth, King of Men, See more"], ["Also known as", "Mairon, Annatar, Gorthaur, the Necromancer, the One Enemy, See more"], ["Race", "Ainur (Maiar)"], ["Culture", "Maia of Morgoth, (initially of Aulë)"], ["Born", "Before the Ainulindalë"], ["Died", "March 25, TA 3019, Battle of the Morannon Notice: Sauron didn't actually die, he was stripped of physical form"], ["Height", "Variable until SA 3319, (physical body)"], ["Weapon", "Powers of the Maiar, the One Ring, dark sorcery, mace, sword"], ["Played by", "Sala Baker, Charlie Vickers, Jack Lowden (prologue)"]], "u": "https://lotr.fandom.com/wiki/Sauron"}, "Tar-Míriel": {"s": "Tar-Míriel or Ar-Zimraphel was the daughter of King Tar-Palantir, and last rightful heir of Númenor. She would rule briefly as Queen Regnant while Ar-Pharazôn's armada defied the Ban of the Valar and incurred Númenor's destruction.", "f": [["Title", "Queen of Númenor"], ["Also known as", "Ar-Zimraphel"], ["Race", "Men"], ["Culture", "Númenóreans (House of Elros, The Faithful)"], ["Born", "SA 3117"], ["Died", "SA 3319, Downfall of Númenor"], ["Eyes", "Bright"], ["Played by", "Cynthia Addai-Robinson"]], "u": "https://lotr.fandom.com/wiki/Tar-M%C3%ADriel"}, "Tar-Palantir": {"s": "Tar-Palantir was the twenty-fourth King of Númenor.", "f": [["Title", "King of Númenor, \"the Farsighted\""], ["Also known as", "Ar-Inziladûn"], ["Race", "Men"], ["Culture", "Númenóreans (House of Elros), The Faithful"], ["Born", "SA 3035"], ["Died", "SA 3255"], ["Weapon", "Aranrúth"], ["Played by", "Ken Blackburn"]], "u": "https://lotr.fandom.com/wiki/Tar-Palantir"}, "Kemen": {"s": "Kemen was a Númenórean nobleman of the Second Age, and the son of Ar-Pharazôn the Golden .", "f": [["Title", "Kemen"], ["Race", "Men"], ["Hair", "Brown"], ["Eyes", "Blue |first seen=\"\"}}"], ["Played by", "Leon Wadham"]], "u": "https://lotr.fandom.com/wiki/Kemen"}, "Eärien": {"s": "Eärien was a Númenórean lady of the Second Age, the daughter of Lord Elendil of Andúnië and sister of Isildur and Anárion in Amazon Studios' television series.", "f": [["Title", "Eärien"], ["Race", "Men"], ["Hair", "Dark brown"], ["Eyes", "Brown |first seen=\"\"}}"], ["Played by", "Ema Horvath"]], "u": "https://lotr.fandom.com/wiki/E%C3%A4rien"}, "Valandil (The Rings of Power)": {"s": "Valandil was a Man of Númenor in the Second Age.", "f": [["Title", "Valandil"], ["Played by", "Alex Tarrant"]], "u": "https://lotr.fandom.com/wiki/Valandil_%28The_Rings_of_Power%29"}, "Bronwyn": {"s": "Bronwyn was a Southlander from the village of Tirharad, in the Second Age.", "f": [["Played by", "Nazanin Boniadi"]], "u": "https://lotr.fandom.com/wiki/Bronwyn"}, "Theo": {"s": "Theo was a resident of Tirharad in the Second Age, and the son of Bronwyn.", "f": [["Race", "Men"], ["Hair", "Black"], ["Eyes", "Brown |first seen=\"\"}}"], ["Played by", "Tyroe Muhafidin"]], "u": "https://lotr.fandom.com/wiki/Theo"}, "Waldreg": {"s": "Waldreg was a Southlander of Tirharad in the Second Age, working at the town pub and later as a commander in Adar's forces.", "f": [], "u": "https://lotr.fandom.com/wiki/Waldreg"}, "Rowan (Southlands)": {"s": "Rowan was a Southlander of the village of Tirharad, in the Southlands.", "f": [], "u": "https://lotr.fandom.com/wiki/Rowan_%28Southlands%29"}, "Ontamo": {"s": "Ontamo was a Man of Númenor in the Second Age.", "f": [], "u": "https://lotr.fandom.com/wiki/Ontamo"}, "Elanor Brandyfoot": {"s": "Elanor Kellamark Brandyfoot, more commonly known as \"Nori\", was a Harfoot hobbit who lived in the Second Age.", "f": [["Race", "Harfoots"], ["Hair", "Brown"], ["Eyes", "Blue-green |first seen=\"\"}}"], ["Played by", "Markella Kavenagh"]], "u": "https://lotr.fandom.com/wiki/Elanor_Brandyfoot"}, "Largo Brandyfoot": {"s": "Largo Brandyfoot was a Harfoot hobbit in the Second Age.", "f": [["Race", "Hobbits"], ["Culture", "Harfoots"], ["Weapon", "|first seen=\"\" |last seen=\"\" |cause of death=}}"], ["Played by", "Dylan Smith"]], "u": "https://lotr.fandom.com/wiki/Largo_Brandyfoot"}, "Marigold Brandyfoot": {"s": "Marigold Brandyfoot was a Harfoot hobbit in the Second Age who dwelt in Rhovanion. She was the second wife of Largo Brandyfoot, and stepmother to Elanor and Dilly Brandyfoot.", "f": [["Race", "Harfoots |first seen=\"\""], ["Played by", "Sara Zwangobani"]], "u": "https://lotr.fandom.com/wiki/Marigold_Brandyfoot"}, "Poppy Proudfellow": {"s": "Poppy Proudfellow was a Harfoot hobbit living in the Second Age. She was a friend of Elanor Brandyfoot.", "f": [["Race", "Harfoots"], ["Hair", "Brown"], ["Eyes", "Brown |first seen=\"\""], ["Played by", "Megan Richards"]], "u": "https://lotr.fandom.com/wiki/Poppy_Proudfellow"}, "Sadoc Burrows": {"s": "Sadoc Burrows was a Harfoot of the Second Age, and a contemporary of fellow Harfoots Elanor Brandyfoot and Poppy Proudfellow. He led their nomadic village as a Trailfinder while they dwelt in the Rhovanion Hills.", "f": [["Race", "Hobbits"], ["Culture", "Harfoots"], ["Weapon", "|first seen=\"\" |last seen=\"\" |cause of death=Stabbed by the Nomad}}"], ["Played by", "Lenny Henry"]], "u": "https://lotr.fandom.com/wiki/Sadoc_Burrows"}, "Malva Meadowgrass": {"s": "Malva Meadowgrass was an ancestor of the Harfoots who lived in Rhovanion in the Second Age. She was part of a nomadic village led by Sadoc Burrows.", "f": [], "u": "https://lotr.fandom.com/wiki/Malva_Meadowgrass"}, "Dilly Brandyfoot": {"s": "Dilly Brandyfoot was the daughter of Largo Brandyfoot and his first wife Rose, and the sister of Elanor (or Nori). She later became the stepdaughter of Marigold upon Largo's marriage to her. A Harfoot hobbit, she resided in Rhovanion in the Second Age.", "f": [], "u": "https://lotr.fandom.com/wiki/Dilly_Brandyfoot"}, "Rose Brandyfoot": {"s": "Rose Brandyfoot was a Harfoot hobbit in the Second Age. She was the first wife of Largo Brandyfoot, and the mother of Elanor and Dilly Brandyfoot. At some point when her children were still young, she died from unknown circumstances, and Largo would go on to marry a Harfoot-woman named Marigold.", "f": [], "u": "https://lotr.fandom.com/wiki/Rose_Brandyfoot"}, "Durin III": {"s": "Durin III was a King of Durin's Folk, and the first bearer of the mightiest of the seven Dwarf Rings, though this was not known to outsiders until the end of the Third Age.", "f": [["Title", "King of Durin's Folk"], ["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Height", "About 4'0\" at least"], ["Played by", "Peter Mullan|birth=Before SA 1500|weapon=Durin's Axe|hair=Grey}}"]], "u": "https://lotr.fandom.com/wiki/Durin_III"}, "Durin IV": {"s": "Durin IV was the King of Durin's Folk and of Khazad-dûm in the late Second Age.", "f": [["Title", "King of Durin's Folk"], ["Race", "Dwarves"], ["Culture", "Durin's Folk"], ["Born", "Late Second Age"], ["Height", "About 4'0\" at least"], ["Hair", "Brown"], ["Played by", "Owain Arthur}}"]], "u": "https://lotr.fandom.com/wiki/Durin_IV"}, "Disa": {"s": "Disa was a Dwarven princess of Khazad-dûm and spouse to Durin IV in the Second Age.", "f": [], "u": "https://lotr.fandom.com/wiki/Disa"}, "Narvi": {"s": "Narvi (originally Ngarvi or Ñarvi) was a Dwarf of Khazad-dûm (Moria) in the mid-Second Age.", "f": [["Born", "Between SA 750 and SA 1500|race=Dwarves|gender=Male|height=About 4'0\" at least|culture=Dwarves of Khazad-dûm|actor=Kevin Eldon, in }}"]], "u": "https://lotr.fandom.com/wiki/Narvi"}, "Gundabale Earthauler": {"s": "Gundabale Earthauler, also known as the Gund, was an ancestor of the Stoors in the Second Age. She led a Stoor village in western Rhûn.", "f": [], "u": "https://lotr.fandom.com/wiki/Gundabale_Earthauler"}, "Thrain (The Rings of Power)": {"s": "Thrain is a dwarf who is set to appear in . He will be portrayed by Eddie Marsan. He is the brother of Durin IV and the son of Durin III.", "f": [], "u": "https://lotr.fandom.com/wiki/Thrain_%28The_Rings_of_Power%29"}, "Dark Wizard": {"s": "", "f": [["Title", "Dark Wizard"], ["Race", "Ainur"], ["Culture", "Maiar (Order of Wizards)"], ["Born", "Before the creation of Arda"], ["Height", "5' 11\""], ["Hair", "Black, greying"], ["Eyes", "Hazel"], ["Weapon", "Wizard's staff"], ["Played by", "Ciarán Hinds"]], "u": "https://lotr.fandom.com/wiki/Dark_Wizard"}, "The Nomad": {"s": "", "f": [["Played by", "Edith Poor|first seen=: |last seen=|relationships=Dark Wizard (leader)|realms=Caras Gaer|race=Mystics|cause of death=Killed by Gandalf}}"]], "u": "https://lotr.fandom.com/wiki/The_Nomad"}, "Tom Bombadil": {"s": "Tom Bombadil was a mysterious entity that lived for much of the world's history, known in the Third Age to dwell in a valley of the Withywindle in the depths of the Old Forest, east of Buckland, and close to the dangerous Barrow-downs.", "f": [["Title", "Eldest, Master"], ["Also known as", "Iarwain Ben-adar, Orald, Forn"], ["Race", "Unknown"], ["Culture", "Forest-folk"], ["Born", "Unknown (before the, coming of Melkor)"], ["Hair", "Brown"], ["Eyes", "Blue"], ["Played by", "Sergei Parshin (Khraniteli), Rory Kinnear"]], "u": "https://lotr.fandom.com/wiki/Tom_Bombadil"}, "Goldberry": {"s": "Goldberry, called the River-daughter, was the wife of Tom Bombadil in the Old Forest at the edge of Buckland.", "f": [["Also known as", "River-daughter"], ["Race", "Unknown"], ["Culture", "Forest-folk"], ["Born", "Unknown"], ["Hair", "Golden"], ["Played by", "Regina Lialeikite (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Goldberry"}, "Gandalf": {"s": "Gandalf, known largely as the Grey and later the White, and originally named Olórin (Quenya), was an Istar (Wizard), dispatched to Middle-earth in the Third Age to combat the threat of Sauron. He joined Thorin Oakenshield and his company to reclaim the Lonely Mountain from Smaug, helped form the Fellowship of the Ring to destroy the One Ring, and helped lead the Free Peoples of the World in the final campaign of the War of the Ring.", "f": [["Title", "Guardian of the Third Age, Istar (Wizard), The Grey, The White Wizard, Servant of the Secret Fire, Wielder of the flame of Anor, Elf-friend"], ["Race", "Ainur"], ["Culture", "Maiar (Guardians, Order of Wizards)"], ["Born", "Before the creation of Arda"], ["Died", "January 25, TA 3019, Battle of the Peak (physical death only, resurrected); Immortal"], ["Height", "5' 6\", 5' 11\" (~1.8 m) in"], ["Hair", "Grey, later white"], ["Eyes", "Blue"], ["Weapon", "Glamdring, Narya, Wizard's staff"], ["Played by", "Ian McKellen (& live-action films), Daniel Weyman, Victor Kostetskiy (Khraniteli)"]], "u": "https://lotr.fandom.com/wiki/Gandalf"}, "Khamûl": {"s": "Khamûl was one of the nine Ringwraiths second to the Witch-king, in Middle-earth. During the Third Age, he held Dol Guldur as Sauron's lieutenant. After the Witch-king was slain, he became the Lord of Nazgûl for a short period.", "f": [["Title", "Lord of the Nazgûl, Lord of Rhûn, Lieutenant of Dol-Guldur"], ["Also known as", "Shadow of the East, The Black Easterling, Khamûl the Easterling"], ["Race", "Men (originally)"], ["Culture", "Nazgûl (Ringwraiths), formerly Easterlings"], ["Born", "Second Age"], ["Died", "March 25, TA 3019, Battle of the Morannon"], ["Weapon", "Sword, Morgul-blade"], ["Played by", "Zubin Varla}}"]], "u": "https://lotr.fandom.com/wiki/Kham%C3%BBl"}, "Damrod (The Rings of Power)": {"s": "Damrod was a hill-troll of the Second Age who lived in the Grey Mountains, who at some point joined the ranks of Adar during Sauron's rise to power.", "f": [["Title", "Damrod|image=Damrod - TRoP.jpg"]], "u": "https://lotr.fandom.com/wiki/Damrod_%28The_Rings_of_Power%29"}, "Mairen (The Rings of Power)": {"s": "Mairen was a woman of Númenor in the Second Age, and the fiancée of Ontamo, Isildur and Valandil's friend.", "f": [], "u": "https://lotr.fandom.com/wiki/Mairen_%28The_Rings_of_Power%29"}, "Médhor": {"s": "Médhor was a Silvan Elf stationed to watch over the settlements of Men in the Southlands in the Second Age.", "f": [], "u": "https://lotr.fandom.com/wiki/M%C3%A9dhor"}, "Miles Brightapple": {"s": "Miles Brightapple was a Harfoot hobbit in the Second Age. He was lost while migrating when he was stuck in the snows of the mountain pass.", "f": [], "u": "https://lotr.fandom.com/wiki/Miles_Brightapple"}, "Hagen": {"s": "Hagen was a man of the Southlands in the Second Age, who to avoid death, swore to serve Adar along with many of his countrymen. Betrothed to the woman Estrid, he and the other men loyal to Adar followed those who escaped to Pelargir. Despite being briefly imprisoned by two Ents for their felling of trees, he was released and reunited with Estrid after Isildur and Arondir's intervention.", "f": [], "u": "https://lotr.fandom.com/wiki/Hagen"}};
